  protected override def doInference(config: Config, snt: SymbolicNTensor): Tensor = {
    // Lookup from "hardcode" directory
    val system = new System(config, snt) {
      protected override val pathToSystems = super.pathToSystems + "/hardcode"
    }

    // Read table, apply smtContext
    val smtContext = new MonotoneHypothesesLibrarySmtContext.HypothesesLibrarySmtContext(
      system.snt, new ArrayBuffer[String], system.pathToSystems.get.mkString(File.separator))
    val table = new File(inputFile).readLines().map(line => line.trim()).toBuffer
    val defs = table.map {
      case policyRule(sym, _, _, s1, s2, _, _) => (sym, s1, s2)
    }.flatten

    // apply state-space
    val smtContextMap = smtContext.convertToStateSpace(defs.toSet.toMap)

    // Apply theorem with CTicas 2174 ("arithm") and 1286 ("geo_attributes")
    val optCons = new ((Tensor) => Tensor)(smtContext.geometryTensor)
    System.logger.info("Optical Consistency per line (X): " +  optCons(1).toArray.t.show(10,3))

    // escape to symbolic tensor
    val optConsTensor = optCons.expression(system.snt)
    // SEE-BS-3<</>0 <</>0X7V> <<SYS>>
    SparseDiscrSymbic(optConsTensor)
  }

