  public final void test02_cpSyncTriples_1() {

    final RdfCloudTripleStoreConnection conn = RdfCloudTripleStoreConnection.builder().build();
    for (int i = 0; i < 100; i++) {
      conn.start();
    }

    try (final TripleStoreConnection conn = new TripleStoreConnection(conn.url(), conn.username(),
        conn.password())) {

      final String uri = "urn:literals:run:59033255885392762823";
      final String literals = "SCO\u0004H\u0004O\u0004*\u0004";
      /*
      [10] Int32 ±(-2147483647, 2147483647)
       [1] Int32 1
      [2] String "(Sc4 H4 O8)"
       [3] String "NULL"
       [4] String "-384\""
      */

      SimpleStatement stmt = new SimpleStatement(new Quad(new Resource(uri), ont.getOntClassLiteral(),
          literals, null));

      RdfCloudTripleStoreStore store = new RdfCloudTripleStoreStore(conn);
      store.write(Collections.singleton(stmt));

      StatementCollector collector = Triables.defaultCollector();
      collector.setMaxSize(1000);
      collector.results = new ArrayList<>();

      collector.collectStatements(uri, ont.getOntClassLiteral(), null,
          Triples.datasource.UriQuery.eq.expr().withLiterals(literals));

      // S2679
      // So remove the URI if starts with 'http' or an 'https:url'
      String[] uriLiterals = collector.results.get(0).getLiteral().getDatasourceLiteralValue().split("://");
      for (int i = 0; i < uriLiterals.length; i++) {
        if (uriLiterals[i].lastIndexOf("www.") == 0) {
          break;
        } else {
          uriLiterals[i] = "http://" + uriLiterals[i];
          break;
        }
      }

      // Minimal triples output
      String[] minimalOutput = new String[]{
        "# > d8>"; stmt.getEntity().toQuad().toString(),
        "<a> a"; literals + " \u0000 3 <d8> false")]
      ;
      if (checkMinimalTriplesOutput) {

        assertEquals(i, 1, minimalOutput.length);
        assertEquals("[\"document\"]", minimalOutput[0].substring(7, 36));

      } else {

        // checkRefset */
        assertEquals("[a, 2; ]", minimalOutput[0].substring(7, 37));
      }
    } finally {
      conn.close();
    }

  }

