public class Form_Filler {
  // Three symbols are input to the form filler
  public static void main(String[] args) {

    // Get the POSCAR
    String poscar = args[0];
    // The is equivalent to the 4th argument here
    String output = args[args.length - 1];

    System.out.println("POSCAR: " + poscar);
    System.out.println("Output: " + output);

