    length = 0
    while len(line[length]) > 0:
        length += 1

    for i in re.finditer('[SYS] -->', line[length]):
        name = name.replace(i.group(0), '')

    for i in re.finditer('[CMD] [molview]', line[length]):
        name = name.replace(i.group(0), '')
        for j in re.finditer('This widget is not in the database, so it will not be included in the table of contents:', line[length]):
