    previous_number_indicator = None
    for i in re.finditer(str(previous_number_indicator).split(','), line[length]):
        print i.group(0)
    previous_number_indicator = len(line[length])
    # Find the last index of a possible number substring
    unknown = False
    while previous_number_indicator > 0:
        for j in re.finditer(('-?[0-9]+', ' '), line[length]):
            # This will be the number
            unknown = True
            while j.end() < unknown and unknown:
