                    print '-'
                if unknown:
                    # The unknown number may have been captured in the last line
                    # if so, put back what was there to preserve the string or list
                    if j.end() == line[length] - 1:
                        j.end(-2)
                    print ',', j.end()
                    print '-'
                combination = j.group().replace(',', ' ')
                # Remove leading and trailing spaces, commas, % symbols, line number indicator
                cleanline = ' '.join(line[length][j.start():j.end()] - [',', '%', 'm']).strip()
                # Check to see if this is the system's name and if so, remove it
                if sys.argv[1] in cleanline:
                    cleanline = ' '.join(''.join(map(str.strip, i)).replace(' ', '') for i in cleanline).strip()
                # Put back the long line number
                cleanline = cleanline + ' ' + ','.join(line[length][j.end():])
                next_number_indicator = j.start()
            if unknown:
                print '0'
            if unknown and not next_number_indicator == len(line[length]) and next_number_indicator != (None, 0, len(line[length])):
                print '-'
                empty_line_indicator = previous_number_indicator - 1
        previous_number_indicator = next_number_indicator

    # Actual line cleaning
    if unknown:
        print '#'

    length = next_number_indicator
    # Update the entire length in this section starting to include the name
    while len(line[length]) > 0:
        length += 1

    for i in re.finditer('<SYS>', line[length]):
        name = ''.join(' ').lower().replace(re.findall(str(i.end()), line[length])[0], '')
        print '\t', name

    # Ignore empty last line
    if previous_number_indicator == len(line[length]):
        print '.'

if __name__ == '__main__':
    import sys
    bleach_1(sys.argv[1], sys.argv[2])
