        Console.printLine("[PEPO] propagaate_movement [Px] = " + x + " [Pd] = " + y + " [t] = " + time);
        // if (y <= 0) return 0;
        // you need to enter the game, or do not press enter.
        // a dragging must stop when arriving to = 0, and to set a maximum <MaxTopSpeed>
        if (y <= 0 && time <= minimum_time_following_distance)
            return 0;

        double distance_following = Math.sqrt(x * x + y * y);
        return 1.0f + Math.pow(follower_speed, 2) * (1.0f + impulse.dampingValues[0]) * follower_speed
                * (Math.max(0.0f, time - distance_following))
                *propagaate_location_x(x, time, minimum_time_following_distance, distance_following)
                / distance_following;
    }

    public static double propagaate_location_x(final double x, final double t, final double minimum_time_following_distance,
                                                 final double distance_following) {

        // description of the algorythm:
        //
        // the propagaation of an object starts at the current position
        //
        // then it evaluates passing x to the currrent position
        //
        // - - - calculate the travel time - - -
        final double time_difference = time - t; // 3 seconds will equal 3.

        // - - - the different speed limits for the property - - -
        double deniers_difference = Math.min(100.0d, absorption), maxSpeedDistance = 0.25,
                maxSpeedThreshold = 5.0;

        double difference = (distance_following + maxSpeedDistance) - (Math.max(0.0d, time_difference));
        deniers_difference = -deniers_difference;

        // - - - calcultate the max speed - - -
        double moveSpeedMagnitude = tempPerMaxSpeedThreshold / (1.0d + deniers_difference * deniers_difference);

        return moveSpeedMagnitude * time_difference;
    }
