Do this:

\begin{code}
export RXNEXM_ARGS=normalize=1.0000 computation_probe_alignment=SUC-GCA15-NN-GCA15
export ACCRXN_ARGS=normalization=HoBiRh
./prefix/nohup ./predictor_simple_morphology.py dyn -predgens=".rets" infile=$INFILE -pred_params="./POSTSCRIPT/prefix/parameter$SHH" infile=$RESULT > result.stencil
\end{code}

Either way you'll have "input domain constraint failed" because neither dyn nor infile would be properly specified: they're actually, globally known values.

