program solve

use 'capm' 1.4;

implicit none;
real*8, complex*8;

implicit none
intrinsic calculate_bond_length(A::intr, B::intr, C::intr, D::intr,
                                E::intr, F::intr, G::intr, H::intr,
                                I::intr, J::intr, K::intr, L::intr,
                                M::intr, N::intr, O::intr);

implicit none
function calculate_bond_length(A::intr, B::intr, C::intr, D::intr,
                              E::intr, F::intr, G::intr, H::intr,
                              I::intr, J::intr, K::intr, L::intr,
                              M::intr, N::intr, O::intr)
direct

Integer k, h, i, s, u, t, v, l, bdim;
Complex b, c, d, e;

bdim = abs(A) + abs(B) + abs(C) + abs(D) + abs(E) + abs(F) + abs(G) + abs(H) +
            abs(I) + abs(J) + abs(K) + abs(L) + abs(M) + abs(N) + abs(O);

if (mod(bdim, 2) > 0) gemm(2, 3, A, -B, A, 3, true);
if (mod(bdim, 2) > 0) gemm(3, 2, -B, A, B, 3, true);
if (mod(bdim, 3) > 0) gemm(3, 3, C, -D, C, 3, true);
if (mod(bdim, 3) > 0) gemm(3, 3, D, -C, D, 3, true);

k = a0; s = a1; u = a2; t = a3; v = a4; h = a5; i = a6;
c = (B+D)*k; d = 0.0; b = pinv(C-0.0*D)*h;
e = (A+C)*0.0;

for (i=1, i<=(bdim-1), i++) d = index(b,i,2);
b = b - e*b - h*b;

for (i=1, i<=(bdim-1), i++) e = index(b,i,1);
e = e + h*b + a(i,6)*d;

for (i=1, i<=(bdim), i++) e = index(e,i,1);
e = e + h*b + a(i,1)*d;

a(i,1); a(i,3);
end

end program solve;

end

dimension Systems = (12:601) female;
solve;
[program]
solve;
\end{code}

