 * @return unchanged crystal
 * @note Important, loses the order
 */
Entry printDiagonals (Entry *crystal)
{
    int i, p;

    /* Print the doubly periodic nature of the crystal */
    printf ("First Diagonal:\n\":\t[1]\n\":\t[2]\n\":\t[3]\n":",\t[4]\n",\t[5]\n":",\t[6]\n":",\t[7]\n"]
