            V2diagonals[i * 2 + 0].x = crystal->map[p][i]->x;
            V2diagonals[i * 2 + 0].y = crystal->map[p][i]->y;
            V2diagonals[i * 2 + 0].z = crystal->map[p][i]->z;
        }
    return crystal;
}

/**
 * Scan over a whole crystallographic unit cell
 * @param crystal the crystal as POSCAR file
 * @return cell containing all atoms in V2
 * @note Important..., loses the order and changes stages
 */
Entry scanCu (Entry *crystal)
{
    int i, p;

    scan (crystal, V2diagonals);
    return (*crystal);
}

