        ilk_nodes = deepcopy(ilk_nodes)
        for k, v in six.iteritems(ilk_nodes):
            if k == 'type':
                continue
            ilk_nodes[k] = self.P * v
        return ilk_nodes

    def last(self, i):
        """Calculate last restriction strength"""
        return self.P * self.P_inv[i]

