        """This function replaces one expression in the expression tree
        with the given expression.  The last value of each evaluation
        of the expression is the replacement value.
        """
        tmp = self
        for k, v in replacement.iters():
            tmp = tmp.replace(k, replacement[k])
        return tmp

    def add_last(self, replacement, last=1):
        tmp = self
        for k, v in six.iteritems(replacement):
            tmp = tmp.replace(k, replacement[k])
        return tmp

